import{_ as r,o as n,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Hilfe und Fortbildung zum Reportdesigner","description":"","frontmatter":{"title":"Hilfe und Fortbildung zum Reportdesigner","source_pageid":1614,"source_revision":6815},"headers":[],"relativePath":"reporting/reportdesigner/reportdesigner-hilfe-wissen-themenuebersicht.md","filePath":"reporting/reportdesigner/reportdesigner-hilfe-wissen-themenuebersicht.md"}'),s={name:"reporting/reportdesigner/reportdesigner-hilfe-wissen-themenuebersicht.md"};function a(o,e,l,d,u,h){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="hilfe-und-fortbildung-zum-reportdesigner" tabindex="-1">Hilfe und Fortbildung zum Reportdesigner <a class="header-anchor" href="#hilfe-und-fortbildung-zum-reportdesigner" aria-label="Permalink to &quot;Hilfe und Fortbildung zum Reportdesigner&quot;">​</a></h1><p>Nutzen Sie das Glossar und die Problemlösungen für konkrete Fragen. Für weitergehende Unterstützung finden Sie Verweise auf Forum, Fortbildungen und Herstellerdokumentation.</p><p><a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a></p><h2 id="reportdesigner-–-hilfe-und-wissen" tabindex="-1">Reportdesigner – Hilfe und Wissen <a class="header-anchor" href="#reportdesigner-–-hilfe-und-wissen" aria-label="Permalink to &quot;Reportdesigner – Hilfe und Wissen&quot;">​</a></h2><p>Diese Seite bündelt Lern- und Hilfsressourcen zum Reportdesigner in <strong>SchILD-NRW 3</strong>. Hier finden Sie Informationen zur Kompatibilität von Reports aus SchILD-NRW 2, Links zu Fortbildungsangeboten unseres Moderationsteams und einen Link zu unserem Forum für ganz individuelle Anfragen.</p><p>Der Hersteller bietet deutschsprachige PDF-Anleitungen zum Reportdesigner an. Die grundlegende Anleitung führt schrittweise zum ersten eigenen Report. Eine vertiefende Anleitung erklärt die Programmieroberfläche. Die Links finden Sie unten unter <strong>Vertiefende PDF-Tutorials</strong>.</p><h3 id="glossar" tabindex="-1">Glossar <a class="header-anchor" href="#glossar" aria-label="Permalink to &quot;Glossar&quot;">​</a></h3><ul><li><a href="/reporting/reportdesigner/glossar-zum-reportdesigner.html">Begriffe des Reportdesigners</a></li></ul><p>Viele neue Begriffe können schnell verwirren. Das Glossar bietet hier schnelle Hilfe.</p><h3 id="informationen-zur-kompatibilitat" tabindex="-1">Informationen zur Kompatibilität <a class="header-anchor" href="#informationen-zur-kompatibilitat" aria-label="Permalink to &quot;Informationen zur Kompatibilität&quot;">​</a></h3><ul><li><a href="/reporting/archiv/kompatibilitaet-der-reports-in-schild-nrw-2-und-schild-nrw-3.html">Reports zwischen SchILD-NRW 2 und 3 umstellen</a></li></ul><p>Erfahren Sie, wann und ob Reports aus SchILD-NRW 2 in SchILD-NRW 3 genutzt werden können</p><h3 id="support-und-fortbildung" tabindex="-1">Support und Fortbildung <a class="header-anchor" href="#support-und-fortbildung" aria-label="Permalink to &quot;Support und Fortbildung&quot;">​</a></h3><ul><li><a href="https://schulverwaltungsinfos.nrw.de/svws/forum/" target="_blank" rel="noreferrer">Link zum SchILD-NRW 3 Anwenderforum</a></li></ul><p>Lassen Sie sich von erfahrenen Anwendern im Forum ganz individuell helfen</p><ul><li><a href="https://www.svws.nrw.de/service/fortbildungen" target="_blank" rel="noreferrer">Fortbildungen der Bezirksregierungen</a></li></ul><p>Nutzen Sie das kostenlose Fortbildungsangebot der Bezirksregierungen für Angestellte des Landes NRW</p><h3 id="vertiefende-pdf-tutorials" tabindex="-1">Vertiefende PDF-Tutorials <a class="header-anchor" href="#vertiefende-pdf-tutorials" aria-label="Permalink to &quot;Vertiefende PDF-Tutorials&quot;">​</a></h3><ul><li><a href="https://www.digital-metaphors.com/download/documentation/#LearningReportBuilder" target="_blank" rel="noreferrer">Link zu den deutschsprachigen Tutorials von Digital-Metaphors</a></li></ul><p>Lernen Sie die Funktionsweise des Reportdesigners mit Hilfe dieses ausführlichen Handbuchs</p><ul><li><a href="https://www.digital-metaphors.com/support/" target="_blank" rel="noreferrer">Link zur Support-Seite von Digital-Metaphors</a></li></ul><p>Lernen Sie die umfangreichen Möglichkeiten der Programmierung im Reportdesigner kennen</p><h3 id="problemlosungen" tabindex="-1">Problemlösungen <a class="header-anchor" href="#problemlosungen" aria-label="Permalink to &quot;Problemlösungen&quot;">​</a></h3><ul><li><a href="/reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.html">Grafikfehler in Reports beheben</a></li></ul><p>Eine Grafik wird nicht angezeigt? Erfahren Sie hier, wie Sie das Problem lösen.</p><ul><li><a href="/reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.html">Schriftarten und Sonderzeichen in PDF-Ausgaben</a></li></ul><p>Ein gedrucktes PDF-Dokument enthält eine seltsame Schrift? Erfahren Sie hier, wie sie Schriftarten einbetten.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Reportdesigner_Hilfe_%26_Wissen_Themen%C3%BCbersicht" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6815.</p>',29)])])}const f=r(s,[["render",a]]);export{g as __pageData,f as default};
